package magpie

import (
	"context"
	"errors"
	"fmt"

	"github.com/portwatcher/lydiabox/internal/store"
)

func isNotFound(err error) bool {
	return errors.Is(err, store.ErrNotFound) || errors.Is(err, ErrNotFound)
}

// provisionKey makes sure magpie has the named VM gateway key and that its
// secret is the one stored (encrypted) in the host database.
//
// The secret is generated by LydiaBox (not "sk-magpie-..." so magpie accepts
// it as the caller's own value) and stored before it is registered, so a
// crash between the two steps only causes a re-registration. magpie keeps
// key IDs stable; the stored ID tells whether the registered key is ours.
func (s *Supervisor) provisionKey(ctx context.Context, admin AdminAPI) error {
	secret, err := s.secret(ctx, secretGatewayKey, func() (string, error) { return randomToken("lbx-gw-", 24) })
	if err != nil {
		return err
	}
	storedID, err := s.opts.Secrets.GetMagpieSecret(ctx, s.opts.TenantID, secretGatewayKeyID)
	if err != nil && !isNotFound(err) {
		return fmt.Errorf("magpie: load gateway key id: %w", err)
	}
	keys, err := admin.ListGatewayKeys(ctx)
	if err != nil {
		return err
	}
	var current *GatewayKey
	for i := range keys {
		k := &keys[i]
		if k.Name != GatewayKeyName {
			continue
		}
		if storedID != "" && k.ID == storedID && current == nil {
			current = k
			continue
		}
		// A key with our name that we did not register (for example after
		// the state database was reset): its secret is unknown, replace it.
		if err := admin.RemoveGatewayKey(ctx, k.ID); err != nil {
			return fmt.Errorf("magpie: remove stale gateway key: %w", err)
		}
	}
	if current != nil {
		if current.Off {
			if err := admin.SetGatewayKeyOff(ctx, current.ID, false); err != nil {
				return err
			}
		}
		s.gatewayKey.Store(secret)
		return nil
	}
	k, err := admin.AddGatewayKey(ctx, GatewayKeyName, secret)
	if err != nil {
		return fmt.Errorf("magpie: add gateway key: %w", err)
	}
	if k.Secret != "" && k.Secret != secret {
		return fmt.Errorf("magpie: gateway key registered with an unexpected secret")
	}
	if err := s.opts.Secrets.PutMagpieSecret(ctx, s.opts.TenantID, secretGatewayKeyID, k.ID); err != nil {
		return fmt.Errorf("magpie: save gateway key id: %w", err)
	}
	s.gatewayKey.Store(secret)
	s.log.Info("provisioned magpie gateway key", "name", GatewayKeyName, "id", k.ID)
	return nil
}

// RotateGatewayKey replaces the VM gateway key with a new secret. The old
// key stops working at once.
func (s *Supervisor) RotateGatewayKey(ctx context.Context) error {
	admin, err := s.Admin()
	if err != nil {
		return err
	}
	secret, err := randomToken("lbx-gw-", 24)
	if err != nil {
		return err
	}
	if err := s.opts.Secrets.PutMagpieSecret(ctx, s.opts.TenantID, secretGatewayKey, secret); err != nil {
		return err
	}
	if err := s.opts.Secrets.PutMagpieSecret(ctx, s.opts.TenantID, secretGatewayKeyID, "-"); err != nil {
		return err
	}
	return s.provisionKey(ctx, admin)
}
